#!/usr/bin/env Rscript

# ==========================================================
# Script   : objective64_qc_plot.R
# Purpose  : Retain an exploratory or secondary historical analysis for transparent provenance
# Inputs   : see data/README.md and config/paths.yml
# Outputs  : historical workspace outputs; not generated by run_all.sh
# Paper    : Not a final-results workflow entry point
# Seed     : see config/params.yml
# Runtime  : not benchmarked in the public release
# Last run : see provenance/source_provenance.csv
# Source   : guarded-workspace:objective64_evidence_package_20261020/scripts/plot_objective_rebuild_qc.R
# ==========================================================
# QC figures only. All analytical quantities are read from locked rebuild outputs.
suppressPackageStartupMessages({ library(ggplot2) })

base_dir <- normalizePath(getwd(), mustWork = TRUE)
root_dir <- normalizePath(file.path(base_dir, ".."), mustWork = TRUE)
results_dir <- file.path(base_dir, "results")
fig_dir <- file.path(base_dir, "figures")
dir.create(fig_dir, recursive = TRUE, showWarnings = FALSE)

theme_objective <- function() {
  theme_classic(base_size = 7, base_family = "Arial") +
    theme(
      axis.line = element_line(linewidth = 0.35, colour = "black"),
      axis.ticks = element_line(linewidth = 0.35, colour = "black"),
      axis.title = element_text(size = 7),
      axis.text = element_text(size = 6.5),
      plot.title = element_text(size = 8, face = "bold"),
      plot.subtitle = element_text(size = 6.4, colour = "grey30"),
      legend.title = element_text(size = 6.5),
      legend.text = element_text(size = 6.2),
      plot.margin = margin(5, 6, 5, 6)
    )
}

save_cairo <- function(plot, stem, width_mm = 89, height_mm = 72, dpi = 600) {
  width_in <- width_mm / 25.4
  height_in <- height_mm / 25.4
  svglite::svglite(file.path(fig_dir, paste0(stem, ".svg")), width = width_in, height = height_in)
  print(plot)
  grDevices::dev.off()
  grDevices::cairo_pdf(file.path(fig_dir, paste0(stem, ".pdf")), width = width_in, height = height_in, family = "Arial")
  print(plot)
  grDevices::dev.off()
  grDevices::png(file.path(fig_dir, paste0(stem, ".png")), width = width_in, height = height_in, units = "in", res = dpi, type = "cairo")
  print(plot)
  grDevices::dev.off()
}

rho_label <- function(rho, p) {
  p_text <- if (p < 0.001) "P < 0.001" else paste0("P = ", format.pval(p, digits = 2))
  paste0("Spearman rho = ", sprintf("%.3f", rho), "\n", p_text)
}

# 1. Primary repeat-level C-index distribution.
repeat_stats <- read.delim(file.path(results_dir, "NESTED_CV_REPEAT_LEVEL_RESULTS.tsv"), check.names = FALSE)
if (nrow(repeat_stats) != 20L) stop("Expected 20 repeat-level C-index values.")
set.seed(1001)
p_repeat <- ggplot(repeat_stats, aes(x = "Held-out repeats", y = repeat_cindex)) +
  geom_hline(yintercept = 0.50, linetype = "dashed", colour = "grey45", linewidth = 0.35) +
  geom_boxplot(width = 0.34, fill = "#D9EAF4", colour = "#2B6C8A", outlier.shape = NA, linewidth = 0.4) +
  geom_jitter(width = 0.075, height = 0, size = 1.4, colour = "#2B6C8A", alpha = 0.9) +
  annotate("text", x = 1, y = max(repeat_stats$repeat_cindex) + 0.009, hjust = 0.5, family = "Arial", size = 2.4,
    label = paste0("Mean = ", sprintf("%.3f", mean(repeat_stats$repeat_cindex)), "; n = 20 repeats")) +
  coord_cartesian(ylim = c(0.48, max(repeat_stats$repeat_cindex) + 0.021), clip = "off") +
  labs(title = "Repeat-level held-out discrimination", subtitle = "Within-fold concordance counts aggregated across 10 outer folds per repeat", x = NULL, y = "Harrell C-index") +
  theme_objective()
save_cairo(p_repeat, "objective_repeat_level_cindex")

# 2. Permutation null.
null <- read.delim(file.path(results_dir, "PERMUTATION_NULL.tsv"), check.names = FALSE)
perm <- read.delim(file.path(results_dir, "PERMUTATION_SUMMARY.tsv"), check.names = FALSE)
if (nrow(null) != 499L || perm$n_permutations[1] != 499L) stop("Expected all 499 permutation results.")
p_perm <- ggplot(null, aes(x = mean_outer_test_cindex)) +
  geom_histogram(binwidth = 0.008, boundary = 0.5, fill = "#B9C9D8", colour = "white", linewidth = 0.18) +
  geom_vline(xintercept = perm$observed_statistic[1], colour = "#B02A37", linewidth = 0.65) +
  annotate("text", x = perm$observed_statistic[1], y = Inf, vjust = 1.6, hjust = 1.03, family = "Arial", size = 2.4, colour = "#B02A37",
    label = paste0("Observed = ", sprintf("%.3f", perm$observed_statistic[1]), "\nEmpirical P = ", sprintf("%.3f", perm$empirical_p[1]))) +
  labs(title = "Permutation null: fixed 5-fold nested-CV statistic", subtitle = "499 complete profile permutations; vertical line is observed statistic", x = "Mean held-out C-index", y = "Number of permutations") +
  theme_objective()
save_cairo(p_perm, "objective_permutation_null")

# 3. Model selection stability.
stab <- read.delim(file.path(results_dir, "GENE_SELECTION_STABILITY_NESTEDCV.tsv"), check.names = FALSE)
top_stab <- head(stab[order(-stab$selection_frequency, stab$gene), ], 30L)
top_stab$gene <- factor(top_stab$gene, levels = rev(top_stab$gene))
top_stab$direction <- ifelse(top_stab$median_nonzero_coefficient < 0, "Negative median coefficient", "Positive median coefficient")
p_stab <- ggplot(top_stab, aes(x = selection_frequency, y = gene, colour = direction)) +
  geom_segment(aes(x = 0, xend = selection_frequency, yend = gene), colour = "grey78", linewidth = 0.35) +
  geom_point(size = 1.65) +
  scale_colour_manual(values = c("Negative median coefficient" = "#2B6C8A", "Positive median coefficient" = "#B02A37")) +
  scale_x_continuous(limits = c(0, 1), breaks = seq(0, 1, 0.25), expand = expansion(mult = c(0, 0.02))) +
  labs(title = "Outer-fit selection stability", subtitle = "Top 30 of 492 objective-universe genes; denominator = 200 outer models", x = "Selection frequency", y = NULL, colour = NULL) +
  theme_objective() + theme(legend.position = "bottom", legend.key.width = grid::unit(6, "mm"), axis.text.y = element_text(size = 5.8))
save_cairo(p_stab, "objective_gene_selection_stability", height_mm = 120)

# 4. Objective versus risk-aligned legacy score.
oof <- read.delim(file.path(results_dir, "OOF_PREDICTIONS.tsv"), check.names = FALSE)
obj <- aggregate(oof$oof_linear_predictor, list(patient_id = oof$patient_id), mean)
names(obj)[2] <- "objective_oof_risk"
legacy <- read.csv(file.path(root_dir, "results/04_ML/models/bcell_lasso_score_tcga.csv"), stringsAsFactors = FALSE)
legacy_fit <- survival::coxph(survival::Surv(legacy$OS_time, legacy$OS_status) ~ legacy$risk_score)
alignment <- if (unname(coef(legacy_fit)[1]) >= 0) 1 else -1
plot_legacy <- merge(obj, data.frame(patient_id = legacy$sample_id, legacy_risk = alignment * legacy$risk_score), by = "patient_id", sort = FALSE)
ct_legacy <- suppressWarnings(cor.test(plot_legacy$objective_oof_risk, plot_legacy$legacy_risk, method = "spearman", exact = FALSE))
p_legacy <- ggplot(plot_legacy, aes(x = legacy_risk, y = objective_oof_risk)) +
  geom_point(size = 0.75, alpha = 0.55, colour = "#2B6C8A") +
  geom_smooth(method = "lm", se = FALSE, linewidth = 0.45, colour = "#B02A37") +
  annotate("label", x = -Inf, y = Inf, hjust = -0.06, vjust = 1.35, family = "Arial", size = 2.35, label = rho_label(unname(ct_legacy$estimate), ct_legacy$p.value), fill = "white") +
  labs(title = "Objective versus legacy BIES", subtitle = "Both scores aligned so higher values indicate higher predicted mortality risk", x = "Risk-aligned legacy BIES", y = "Mean cross-fitted objective risk score") +
  theme_objective()
save_cairo(p_legacy, "objective_vs_legacy_scatter")

# 5. Descriptive overlap-free TLS context.
vst <- readRDS(file.path(root_dir, "results/02_WGCNA/vst_top5000.rds"))
surv <- read.csv(file.path(root_dir, "results/04_ML/features/survival_data.csv"), stringsAsFactors = FALSE)
tls_audit <- read.delim(file.path(results_dir, "TLS_OVERLAP_FREE_OBJECTIVE_AUDIT.tsv"), check.names = FALSE)
tls_free <- unlist(strsplit(tls_audit$overlap_free_genes[1], ",", fixed = TRUE))
tls_present <- intersect(tls_free, rownames(vst))
zz <- t(apply(vst[tls_present, surv$sample_id, drop = FALSE], 1L, function(z) as.numeric(scale(z))))
tls_score <- stats::setNames(colMeans(zz, na.rm = TRUE), surv$sample_id)
plot_tls <- data.frame(patient_id = surv$sample_id, tls_overlap_free_score = tls_score[match(surv$sample_id, names(tls_score))])
plot_tls <- merge(obj, plot_tls, by = "patient_id", sort = FALSE)
ct_tls <- suppressWarnings(cor.test(plot_tls$objective_oof_risk, plot_tls$tls_overlap_free_score, method = "spearman", exact = FALSE))
p_tls <- ggplot(plot_tls, aes(x = tls_overlap_free_score, y = objective_oof_risk)) +
  geom_point(size = 0.75, alpha = 0.55, colour = "#4F7D65") +
  geom_smooth(method = "lm", se = FALSE, linewidth = 0.45, colour = "#B02A37") +
  annotate("label", x = -Inf, y = Inf, hjust = -0.06, vjust = 1.35, family = "Arial", size = 2.35, label = rho_label(unname(ct_tls$estimate), ct_tls$p.value), fill = "white") +
  labs(title = "Objective score versus overlap-free TLS", subtitle = paste0("Descriptive association; ", length(tls_present), "/", length(tls_free), " genes available; not external validation"), x = "Overlap-free TLS score", y = "Mean cross-fitted objective risk score") +
  theme_objective()
save_cairo(p_tls, "objective_vs_tls_overlap_free_scatter")

message("Objective rebuild QC figures complete.")
